    const els = { input:$("linkInput"), parseBtn:$("parseBtn"), clipboardBtn:$("clipboardBtn"), clearBtn:$("clearBtn"), autoDownload:$("autoDownload"), status:$("status"), video:$("video"), soundUnlock:$("soundUnlock"), empty:$("empty"), videoTitle:$("videoTitle"), videoAuthor:$("videoAuthor"), diggMini:$("diggMini"), commentMini:$("commentMini"), shareMini:$("shareMini"), collectMini:$("collectMini"), digg:$("digg"), comment:$("comment"), share:$("share"), collect:$("collect"), desc:$("desc"), music:$("music"), cover:$("cover"), downloadUrl:$("downloadUrl"), downloadBtn:$("downloadBtn"), centerDownloadBtn:$("centerDownloadBtn"), commentsBtn:$("commentsBtn"), centerAiBtn:$("centerAiBtn"), onlineCount:$("onlineCount"), vipCode:$("vipCode"), memberUser:$("memberUser"), memberPass:$("memberPass"), vipBtn:$("vipBtn"), loginBtn:$("loginBtn"), vipState:$("vipState"), memberBenefits:$("memberBenefits"), profileInput:$("profileInput"), profilePreviewBtn:$("inspectBtn"), profileFetchProgress:$("profileFetchProgress"), profileProgressText:$("profileProgressText"), profileProgressCount:$("profileProgressCount"), profileProgressBar:$("profileProgressBar"), profileDetected:$("profileDetected"), batchCount:$("batchCount"), batchConcurrency:$("batchConcurrency"), startBatchBtn:$("startBatchBtn"), batchAiBtn:$("batchAiBtn"), collectBatchCommentsBtn:$("collectBatchCommentsBtn"), viewBatchCommentsBtn:$("viewBatchCommentsBtn"), exportJsonBtn:$("exportJsonBtn"), exportItemsCsvBtn:$("exportItemsCsvBtn"), exportScriptsBtn:$("exportScriptsBtn"), exportScriptsCsvBtn:$("exportScriptsCsvBtn"), exportCoversBtn:$("exportCoversBtn"), batchVideosBtn:$("batchVideosBtn"), exportCommentsBtn:$("exportCommentsBtn"), exportCommentsCsvBtn:$("exportCommentsCsvBtn"), refreshBatchBtn:$("refreshBatchBtn"), batchStatus:$("batchStatus"), batchList:$("batchList"), batchSummary:$("batchSummary"), batchCommentsStatus:$("batchCommentsStatus"), batchCommentsList:$("batchCommentsList"), queuePosition:$("queuePosition"), queuePriority:$("queuePriority"), profilePreviewList:$("profilePreviewList"), loadMoreProfileBtn:$("loadMoreProfileBtn"), commentWorkspace:$("commentWorkspace"), commentsStatus:$("commentsStatus"), commentsList:$("commentsList"), commentCollectMode:$("commentCollectMode"), commentTargetCount:$("commentTargetCount"), collectCurrentCommentsBtn:$("collectCurrentCommentsBtn"), commentProgressBar:$("commentProgressBar"), commentCollectionList:$("commentCollectionList"), commentSearchInput:$("commentSearchInput"), commentSearchBtn:$("commentSearchBtn"), commentSearchClearBtn:$("commentSearchClearBtn"), selectAllCommentsBtn:$("selectAllCommentsBtn"), clearCommentSelectionBtn:$("clearCommentSelectionBtn"), commentSelectedCount:$("commentSelectedCount"), exportSelectedCommentsJsonBtn:$("exportSelectedCommentsJsonBtn"), exportSelectedCommentsCsvBtn:$("exportSelectedCommentsCsvBtn"), exportCurrentCommentsJsonBtn:$("exportCurrentCommentsJsonBtn"), exportCurrentCommentsCsvBtn:$("exportCurrentCommentsCsvBtn"), loadMoreCommentsBtn:$("loadMoreCommentsBtn"), aiPrompt:$("aiPrompt"), aiTranscriptBtn:$("aiTranscriptBtn"), aiScriptBtn:$("aiScriptBtn"), aiRewriteBtn:$("aiRewriteBtn"), aiTagsBtn:$("aiTagsBtn"), aiStatus:$("aiStatus"), aiResult:$("aiResult"), copyAiBtn:$("copyAiBtn") };
    function extractDouyinUrl(text){ const m=String(text||"").match(/https?:\/\/[^\s"'<>，。！？；、]+/i); if(!m)return""; try{const u=new URL(m[0]);const h=u.hostname.toLowerCase();return (h.endsWith("douyin.com")||h.endsWith("iesdouyin.com")||h.endsWith("amemv.com"))?u.toString():"";}catch{return"";} }
    function isProfileUrl(url){ try{const u=new URL(url);return u.pathname.includes("/user/")||u.pathname.includes("/share/user/");}catch{return false;} }
    function fmt(n){ return n===null||n===undefined?"--":Number(n).toLocaleString("zh-CN"); }
    function statusZh(value){const key=String(value||"").toLowerCase();return ({queued:"\u6392\u961f\u4e2d",running:"\u5904\u7406\u4e2d",completed:"\u5df2\u5b8c\u6210",failed:"\u5931\u8d25",cancelled:"\u5df2\u53d6\u6d88",pending:"\u7b49\u5f85\u4e2d",idle:"\u672a\u5f00\u59cb",success:"\u6210\u529f",active:"\u542f\u7528",disabled:"\u505c\u7528"})[key]||(/[\u4e00-\u9fff]/.test(String(value||""))?String(value):"\u672a\u77e5\u72b6\u6001");}
    function setStatus(el,msg,type){ el.textContent=msg; el.className="status"+(type?" "+type:""); }
    function friendlyError(message){ const text=String(message||"请求失败"); const rules=[[/no video play id or image[_ ]url_list found/i,"\u8be5\u94fe\u63a5\u53ef\u80fd\u662f\u4e3b\u9875\u94fe\u63a5\uff0c\u6b63\u5728\u5c1d\u8bd5\u83b7\u53d6\u4f5c\u54c1\u3002"],[/missing_url|url query parameter is required/i,"\u8bf7\u5148\u8f93\u5165\u6296\u97f3\u94fe\u63a5\u3002"],[/invalid_url|invalid douyin url/i,"\u94fe\u63a5\u683c\u5f0f\u65e0\u6548\uff0c\u8bf7\u68c0\u67e5\u540e\u91cd\u8bd5\u3002"],[/parse_failed|failed to parse/i,"\u5185\u5bb9\u89e3\u6790\u5931\u8d25\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002"],[/unsupported_content|unsupported douyin content/i,"\u6682\u4e0d\u652f\u6301\u8be5\u5185\u5bb9\u7c7b\u578b\u3002"],[/internal_error|internal server error/i,"\u670d\u52a1\u5668\u5904\u7406\u5931\u8d25\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002"],[/membership activation.*batch parsing/i,"请先激活或登录会员后再使用批量功能。"],[/current plan does not include AI/i,"当前套餐不包含 AI 文案能力。"],[/current plan does not include comment/i,"当前套餐不包含评论查看/导出。"],[/rate limit exceeded/i,"请求过于频繁，请稍后再试。"],[/csrf token/i,"登录态校验失败，请刷新页面后重新登录。"],[/找不到 FFmpeg/i,"服务器尚未安装 FFmpeg，真实口播识别暂不可用。"],[/语音识别队列已满/i,"当前识别人数较多，语音识别队列已满，请稍后重试。"],[/小米语音识别|ASR/i,"小米语音识别调用失败，请检查后台模型、接口地址和密钥。"],[/browser profile collector|signed works response|profile collector|\u4e3b\u9875\u91c7\u96c6\u5668/i,"\u4e3b\u9875\u4f5c\u54c1\u8bfb\u53d6\u6682\u65f6\u5931\u8d25\uff0c\u7cfb\u7edf\u5df2\u81ea\u52a8\u91cd\u8bd5\u5907\u7528\u9875\u9762\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002"],[/profile post api status/i,"主页作品接口暂时被抖音限制，请稍后重试或换一个主页链接。"],[/comment list api status/i,"评论接口暂时被抖音限制，请稍后重试。"],[/fetch failed/i,"上游接口请求失败，请稍后重试。"]]; for(const r of rules){if(r[0].test(text))return r[1];} return /[\u4e00-\u9fff]/.test(text)?text:"\u8bf7\u6c42\u5904\u7406\u5931\u8d25\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002"; }
    function requireMemberForBatch(message){ if(state.vipToken)return true; setStatus(els.batchStatus,message||"请先激活或登录会员后再使用批量任务、批量文案和批量导出。","err"); return false; }
    function debounce(fn,ms){ let t; return function(){ clearTimeout(t); const a=arguments; t=setTimeout(function(){ fn.apply(null,a); },ms); }; }
    async function api(path, options){ options=options||{}; const headers=new Headers(options.headers||{}); if(options.body&&!headers.has("content-type"))headers.set("content-type","application/json"); if(state.vipToken)headers.set("authorization","Bearer "+state.vipToken); if(state.vipCsrf)headers.set("x-csrf-token",state.vipCsrf); const res=await fetch(path,Object.assign({},options,{headers})); const json=await res.json().catch(function(){return null;}); if(!res.ok||!json||json.ok===false)throw new Error(friendlyError((json&&json.error&&json.error.detail)|| (json&&json.message) || ("HTTP "+res.status))); return json.data; }
    async function apiStream(path, options, onEvent){ options=options||{}; const headers=new Headers(options.headers||{}); if(options.body&&!headers.has("content-type"))headers.set("content-type","application/json"); if(state.vipToken)headers.set("authorization","Bearer "+state.vipToken); if(state.vipCsrf)headers.set("x-csrf-token",state.vipCsrf); const res=await fetch(path,Object.assign({},options,{headers})); if(!res.ok){const json=await res.json().catch(function(){return null;});throw new Error(friendlyError((json&&json.error&&json.error.detail)||(json&&json.message)||("HTTP "+res.status)));} if(!res.body||!res.body.getReader)throw new Error("\u5f53\u524d\u6d4f\u89c8\u5668\u4e0d\u652f\u6301\u6d41\u5f0f\u8fdb\u5ea6\u3002"); const reader=res.body.getReader();const decoder=new TextDecoder();let buffer="";let result=null;function consume(line){if(!line.trim())return;let event;try{event=JSON.parse(line);}catch{return;}if(event.type==="error")throw new Error(friendlyError(event.detail||event.message||event.code));if(onEvent)onEvent(event);if(event.type==="done")result=event.data;}while(true){const part=await reader.read();buffer+=decoder.decode(part.value||new Uint8Array(),{stream:!part.done});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines)consume(line);if(part.done)break;}if(buffer.trim())consume(buffer);if(!result)throw new Error("\u4e3b\u9875\u4f5c\u54c1\u8fdb\u5ea6\u6d41\u672a\u6b63\u5e38\u5b8c\u6210\u3002");return result; }
    function setProfileProgress(mode,text,current,total){if(!els.profileFetchProgress)return;els.profileFetchProgress.classList.remove("hidden","indeterminate","error");if(mode==="hidden"){els.profileFetchProgress.classList.add("hidden");return;}if(mode==="indeterminate")els.profileFetchProgress.classList.add("indeterminate");if(mode==="error")els.profileFetchProgress.classList.add("error");if(els.profileProgressText)els.profileProgressText.textContent=text||"";const hasTotal=Number(total)>0;const done=Math.max(0,Number(current)||0);const max=hasTotal?Number(total):0;if(els.profileProgressCount)els.profileProgressCount.textContent=hasTotal?(Math.min(done,max)+"/"+max):(mode==="indeterminate"?"\u8bc6\u522b\u4e2d":"--");if(els.profileProgressBar)els.profileProgressBar.style.width=hasTotal?(Math.min(100,Math.round(done/max*100))+"%"):(mode==="indeterminate"?"38%":"0%");if(mode==="indeterminate")els.profileFetchProgress.removeAttribute("aria-valuenow");else els.profileFetchProgress.setAttribute("aria-valuenow",hasTotal?String(Math.min(100,Math.round(done/max*100))):"0");}
    function unlockVideoSound(){ els.video.muted=false; if(els.soundUnlock)els.soundUnlock.classList.add("hidden"); if(els.video.paused)els.video.play().catch(function(){}); }
    function attemptVideoPlayback(){ els.video.muted=false; const attempt=els.video.play(); if(attempt&&attempt.catch)attempt.catch(function(){ els.video.muted=true; const fallback=els.video.play(); if(fallback&&fallback.then)fallback.then(function(){if(els.soundUnlock)els.soundUnlock.classList.remove("hidden");}).catch(function(){}); }); }
    function stopShowcase(){ state.showcaseActive=false; state.showcaseLoading=false; }
    async function playNextShowcase(){ if(!state.showcaseActive||state.showcaseLoading||!DEFAULT_SHOWCASE_URLS.length)return; state.showcaseLoading=true; state.showcaseIndex=(state.showcaseIndex+1)%DEFAULT_SHOWCASE_URLS.length; const index=state.showcaseIndex; try{ let data=state.showcaseItems[index]; if(!data){ data=await api("/api/v1/parse?url="+encodeURIComponent(DEFAULT_SHOWCASE_URLS[index])); state.showcaseItems[index]=data; } if(!state.showcaseActive)return; state.lastData=data; renderResult(data); setStatus(els.status,"\u6b63\u5728\u8f6e\u64ad\u793a\u4f8b\u89c6\u9891\uff1b\u7c98\u8d34\u6296\u97f3\u94fe\u63a5\u540e\u4f1a\u7acb\u5373\u5207\u6362\u3002","ok"); }catch(err){ if(state.showcaseActive)setTimeout(playNextShowcase,1200); }finally{ state.showcaseLoading=false; } }
    function restartShowcase(){ state.showcaseActive=true; state.showcaseIndex=-1; state.lastUrl=""; playNextShowcase(); }
    async function parseLink(raw, source){ const url=extractDouyinUrl(raw); if(!url){setStatus(els.status,"没有识别到抖音链接。","err");return;} if(source!=="manual"&&url===state.lastUrl)return; stopShowcase(); state.lastUrl=url; state.lastTranscript=""; els.input.value=raw; if(isProfileUrl(url)){els.profileInput.value=url; setStatus(els.status,"识别到主页链接，正在加载作品预览..."); await previewProfile(true); return;} setStatus(els.status,"正在解析并生成中心视频预览..."); els.parseBtn.disabled=true; try{const data=await api("/api/v1/parse?url="+encodeURIComponent(url)); state.lastData=data; renderResult(data); setStatus(els.status,"解析成功，视频已居中预览。","ok"); if(els.autoDownload.checked&&data.download&&data.download.download_url)triggerDownload(data.download.download_url,data.download.filename||"douyin-video.mp4");}catch(err){const message=err.message||String(err);if(message.includes("\u8be5\u94fe\u63a5\u53ef\u80fd\u662f\u4e3b\u9875\u94fe\u63a5")){els.profileInput.value=url;setStatus(els.status,"\u8bc6\u522b\u5230\u4e3b\u9875\u94fe\u63a5\uff0c\u6b63\u5728\u83b7\u53d6\u4f5c\u54c1\u9884\u89c8...");await previewProfile(true,false);setStatus(els.status,state.profileItems.length?"\u5df2\u8bc6\u522b\u4e3a\u4e3b\u9875\u94fe\u63a5\uff0c\u4f5c\u54c1\u9884\u89c8\u5df2\u52a0\u8f7d\u3002":"\u4e3b\u9875\u4f5c\u54c1\u8bfb\u53d6\u5931\u8d25\uff0c\u8bf7\u67e5\u770b\u4e0b\u65b9\u63d0\u793a\u3002",state.profileItems.length?"ok":"err");}else setStatus(els.status,message,"err");}finally{els.parseBtn.disabled=false;} }
