    async function loadCollectedComments(reset){ if(!state.lastCommentTaskId)return; clearTimeout(state.commentPollTimer); if(reset){state.commentOffset=0;state.commentItems=[];} try{const path="/api/v1/comments/collection/"+encodeURIComponent(state.lastCommentTaskId)+"?offset="+state.commentOffset+"&limit=100"+(state.commentScopeAwemeId?("&aweme_id="+encodeURIComponent(state.commentScopeAwemeId)):"")+(state.commentKeyword?("&q="+encodeURIComponent(state.commentKeyword)):""); const data=await api(path); state.commentFilteredCount=data.filtered_count||0;state.commentItems=reset?(data.comments||[]):state.commentItems.concat(data.comments||[]);state.commentOffset=state.commentItems.length;state.commentHasMore=!!data.has_more;renderComments();if(els.loadMoreCommentsBtn)els.loadMoreCommentsBtn.classList.toggle("hidden",!state.commentHasMore);const running=updateCommentProgress(data);if(running)state.commentPollTimer=setTimeout(function(){loadCollectedComments(true);},1800);}catch(err){setStatus(els.commentsStatus,err.message||String(err),"err");} }
